const brands=[{id:'lumiere',name:'루미에르 코스메틱',short:'루미에르',initial:'L',color:'#b77ba2',soft:'#f5e5ee',events:3,active:2,sends:'1,240',cost:'86,500원',description:'뷰티 · 팝업스토어 · 브랜드 프로모션',list:[['루미에르 성수 팝업 룰렛','진행 중','854건'],['루미에르 뷰티 위크','종료','386건']]},{id:'novahome',name:'노바홈',short:'노바홈',initial:'N',color:'#6488c1',soft:'#eaf1fb',events:1,active:1,sends:'0',cost:'0원',description:'리빙 · 가전박람회 · 체험 행사',list:[['노바홈 가전박람회 스크래치','검토 중','0건']]},{id:'greenday',name:'그린데이',short:'그린데이',initial:'G',color:'#6d9873',soft:'#eaf5ed',events:1,active:1,sends:'0',cost:'0원',description:'식음료 · 신제품 출시 · 참여형 캠페인',list:[['그린데이 가을 신제품 퀴즈','시작 예정','0건']]}];
const gameTemplates=[{id:'lumiere-wheel',type:'룰렛',en:'SPIN THE WHEEL',title:'오늘의 작은 행운',brand:'LUMIÈRE',headline:'당신의 오늘에<br>작은 빛을 더하세요.',desc:'브랜드 감성을 담은 팝업스토어 경품 룰렛',category:'팝업스토어',stage:'#efdae7',paper:'#fff8fc',ink:'#71526b',accent:'#b77ba2',kind:'wheel'},{id:'nova-scratch',type:'스크래치',en:'SCRATCH & WIN',title:'긁어서 만나는 선물',brand:'NOVA HOME',headline:'새로운 일상,<br>새로운 선물.',desc:'가전박람회·현장에서 바로 확인하는 당첨 카드',category:'현장 경품',stage:'#dee7f2',paper:'#f6f9ff',ink:'#425b7d',accent:'#6b8dbb',kind:'scratch'},{id:'green-quiz',type:'퀴즈',en:'BRAND QUIZ',title:'브랜드를 알아가는 시간',brand:'GREEN DAY',headline:'당신의 취향은<br>어떤 그린인가요?',desc:'신제품 퀴즈와 쿠폰 지급으로 자연스러운 제품 경험',category:'제품 홍보',stage:'#e1eadf',paper:'#f9fcf5',ink:'#527050',accent:'#72946b',kind:'quiz'},{id:'violet-memory',type:'메모리',en:'MEMORY MATCH',title:'같은 제품을 찾아주세요',brand:'STUDIO VIOLET',headline:'기억 속의 선물을<br>찾아볼까요?',desc:'브랜드 제품을 기억하며 즐기는 카드 매칭',category:'제품 홍보',stage:'#e9e0f5',paper:'#fcf9ff',ink:'#695480',accent:'#9173bd',kind:'memory'},{id:'gold-slot',type:'슬롯',en:'LUCKY SLOT',title:'세 번의 반짝이는 행운',brand:'GOLDEN HOUR',headline:'지금 이 순간,<br>행운을 맞춰보세요.',desc:'짧고 직관적인 슬롯으로 현장 분위기를 더하는 이벤트',category:'현장 경품',stage:'#f4e6cc',paper:'#fffaf0',ink:'#957443',accent:'#c79b53',kind:'slot'},{id:'orange-speed',type:'반응속도',en:'TAP CHALLENGE',title:'빠르게, 더 즐겁게',brand:'ORANGE CLUB',headline:'당신의 반응속도를<br>보여주세요!',desc:'기록을 겨루며 다시 참여하고 싶은 타이밍 게임',category:'참여 유도',stage:'#f7e0d2',paper:'#fff8f2',ink:'#9f6544',accent:'#dd9468',kind:'speed'}];
state.brandId='lumiere';state.templateFilter='전체';state.templateSearch='';state.createPrompt='';state.selectedTemplate='lumiere-wheel';state.favorites=[];state.creationCustom=false;
function currentBrand(){return brands.find(b=>b.id===state.brandId)||brands[0]}function currentTemplate(){return gameTemplates.find(t=>t.id===state.selectedTemplate)||gameTemplates[0]}
function gameSketch(t){if(t.kind==='wheel')return '<div class="sample-wheel"></div>';if(t.kind==='scratch')return '<div class="sample-scratch"><span class="scratch-gift">✦</span><span>여기를 긁어 선물을 확인하세요</span></div>';if(t.kind==='quiz')return '<div class="sample-quiz"><span class="quiz-count">QUESTION 01 / 03</span><div class="quiz-question">어떤 순간에 가장 빛나나요?</div><div class="quiz-option">A　나만의 여유를 즐길 때</div><div class="quiz-option">B　새로운 것을 만날 때</div><div class="quiz-option">C　함께하는 순간</div></div>';if(t.kind==='memory')return '<div class="sample-memory">'+['◇','✧','◇','✦','✧','✦','♡','♡','◇'].map((v,i)=>`<div class="memory-cell ${i===0||i===2?'revealed':''}">${i===0||i===2?v:'?'}</div>`).join('')+'</div>';if(t.kind==='slot')return '<div class="sample-slots"><div class="sample-slot">✦</div><div class="sample-slot">✦</div><div class="sample-slot">✦</div></div>';return '<div class="sample-speed">0.24<span style="font-size:9px">s</span></div>'}
function templateStage(t,favorite=true){return `<div class="template-stage" style="--stage:${t.stage};--paper:${t.paper};--ink:${t.ink};--accent:${t.accent}"><span class="template-top-label">${t.en}</span>${favorite?`<button class="template-favorite ${state.favorites.includes(t.id)?'saved':''}" data-favorite="${t.id}" aria-label="${t.title} 즐겨찾기">${state.favorites.includes(t.id)?'♥':'♡'}</button>`:''}<div class="sample-mobile"><div class="sample-brand">${t.brand}</div><div class="sample-title">${t.headline}</div><div class="sample-caption">당신을 위한 작은 선물이 기다리고 있어요.</div>${gameSketch(t)}<div class="sample-cta">${t.kind==='wheel'?'룰렛 돌리기':t.kind==='scratch'?'선물 확인하기':t.kind==='quiz'?'다음 질문':t.kind==='memory'?'게임 시작하기':'도전하기'}</div></div></div>`}
templates=function(){return shell(`<section class="create-hero"><div class="eyebrow">LET'S MAKE SOMETHING PLAYFUL</div><h1>어떤 행사를<br><em>만들고 싶으세요?</em></h1><p class="sub">행사 아이디어를 알려주세요. 게임부터 경품까지, 함께 준비해요.</p><div class="prompt-composer"><textarea id="create-prompt" aria-label="만들고 싶은 행사 설명" placeholder="예: 성수 팝업에서 쓸 핑크 톤 룰렛 이벤트를 만들어줘.\n기프트 세트 10개와 커피 상품권 300개를 경품으로 주고 싶어.">${esc(state.createPrompt)}</textarea><div class="composer-footer"><select id="create-brand" aria-label="행사를 만들 브랜드">${brands.map(b=>`<option value="${b.id}" ${b.id===state.brandId?'selected':''}>${b.name}</option>`).join('')}</select><button class="btn" data-create="generate">✧ AI로 행사 만들기 <span>↑</span></button></div></div><div class="prompt-suggestions">${[['팝업스토어 경품 룰렛','성수 팝업스토어에서 사용할 핑크 톤 경품 룰렛을 만들어줘.'],['박람회 스크래치 이벤트','가전박람회에서 스크래치를 긁으면 당첨을 확인하는 이벤트를 만들어줘.'],['신제품 브랜드 퀴즈','신제품을 소개하는 브랜드 퀴즈 이벤트를 만들어줘.']].map(([label,p])=>`<button data-prompt="${p}">${label} ↗</button>`).join('')}</div></section><div class="create-divider">또는 템플릿에서 시작하세요</div><section><div class="gallery-head"><div><h2>아이디어가 되는 게임들</h2><p class="sub">마음에 드는 디자인을 고르고, 우리 브랜드에 맞게 바꿔보세요.</p></div><input class="gallery-search" id="template-search" placeholder="템플릿 검색" aria-label="템플릿 검색" value="${esc(state.templateSearch)}"></div><div class="gallery-tabs">${['전체','팝업스토어','현장 경품','제품 홍보','참여 유도','즐겨찾기'].map(t=>`<button data-tplfilter="${t}" class="${state.templateFilter===t?'active':''}">${t}</button>`).join('')}</div><div class="template-gallery" id="template-grid">${galleryCards()}</div></section>`)};
function galleryCards(){const list=gameTemplates.filter(t=>(state.templateFilter==='전체'||state.templateFilter===t.category||(state.templateFilter==='즐겨찾기'&&state.favorites.includes(t.id)))&&`${t.title} ${t.type} ${t.desc}`.includes(state.templateSearch));return list.length?list.map(t=>`<article class="template-card" data-component="TemplateCard">${templateStage(t)}<div class="template-info"><div class="template-meta"><span class="template-type">${t.type} · ${t.category}</span><span class="mini-label" style="font-size:8px">모바일 최적화</span></div><h3>${t.title}</h3><p class="template-desc">${t.desc}</p><div class="template-actions"><button data-preview="${t.id}">미리보기 ↗</button><button class="text-link" data-use="${t.id}">이 템플릿 사용 →</button></div></div></article>`).join(''):'<div class="empty-gallery">조건에 맞는 템플릿이 없습니다. 다른 분류를 선택해보세요.</div>'}
function useTemplate(id){state.selectedTemplate=id;state.creationCustom=true;state.generated=false;state.applied=false;state.editorTab='디자인';go('editor');toast(`${currentTemplate().type} 템플릿을 선택했습니다. 브랜드에 맞게 편집하세요.`)}
function previewTemplate(id){const t=gameTemplates.find(t=>t.id===id);app.insertAdjacentHTML('beforeend',`<div class="modal-overlay"><div class="modal template-modal">${templateStage(t,false)}<div><div class="between"><span class="eyebrow">TEMPLATE PREVIEW</span><button data-create="close" aria-label="닫기">✕</button></div><h2>${t.title}</h2><p class="sub mt">${t.desc}</p><span class="template-detail-tag">${t.type}</span><span class="template-detail-tag">모바일</span><span class="template-detail-tag">브랜드 편집</span><p class="small dim mt">로고, 색상, 문구와 경품을 바꿔 우리 행사에 맞게 사용할 수 있습니다.</p><div class="field"><label>적용할 브랜드</label><select id="preview-brand">${brands.map(b=>`<option value="${b.id}" ${b.id===state.brandId?'selected':''}>${b.name}</option>`).join('')}</select></div><button class="btn wide mt" data-use="${id}">이 템플릿으로 시작하기 →</button><p class="mini-label mt">디자인 미리보기 · 실제 경품은 지급되지 않습니다.</p></div></div></div>`);bind()}
workspace=function(){return shell(`${title('BRAND WORKSPACES','브랜드 워크스페이스','관리할 브랜드를 선택하세요. 행사·발송·자료·게스트를 브랜드별로 관리합니다.',btn('＋ 브랜드 추가','brand-new'))}<div class="brand-list">${brands.map(b=>`<section class="panel brand-card"><div class="brand-symbol" style="background:${b.soft};color:${b.color}">${esc(b.initial)}</div><h2>${esc(b.name)}</h2><p class="brand-description">${b.description}</p><div class="brand-card-stats"><div><span class="mini-label">전체 행사</span><strong>${b.events}</strong></div><div><span class="mini-label">진행·예정</span><strong>${b.active}</strong></div></div><button class="btn secondary brand-open" data-brand="${b.id}">워크스페이스 열기 →</button></section>`).join('')}</div><div class="helper mt"><strong>브랜드마다 독립된 운영 공간</strong>선택한 브랜드의 행사와 발송 이력만 표시됩니다. 다른 브랜드로 이동해도 기능별 탭은 유지됩니다.</div>`)};
function brandDetail(){const b=currentBrand();return shell(`<div class="brand-toolbar"><a class="brand-back" href="#workspace">← 전체 브랜드 보기</a><select class="brand-switch" id="brand-switch" aria-label="브랜드 전환">${brands.map(v=>`<option value="${v.id}" ${b.id===v.id?'selected':''}>${esc(v.name)}</option>`).join('')}</select></div>${title('BRAND WORKSPACE',esc(b.name),'이 브랜드의 행사와 데이터, 발송 이력을 따로 관리합니다.',`<span class="badge" style="background:${b.soft};color:${b.color}">브랜드별 분리</span>`)}<div class="editor-tabs">${['행사','발송 이력','브랜드 자료','게스트'].map(t=>`<button data-wstab="${t}" class="${state.wsTab===t?'active':''}">${t}</button>`).join('')}</div>${state.wsTab==='행사'?`<section class="panel"><div class="panel-head"><h2>${esc(b.short)} 행사</h2><button class="btn secondary" data-create="brand-create">＋ 행사 만들기</button></div>${brandRows(b,false)}</section>`:state.wsTab==='브랜드 자료'?`<section class="panel" style="max-width:680px"><h2>브랜드 기본 자료</h2><div class="field"><label>로고 워드마크</label><input value="${esc(b.name)}"></div><div class="field"><label>대표 색상</label><input type="color" value="${b.color}" style="width:60px;height:45px"></div>${btn('저장','save')}</section>`:state.wsTab==='게스트'?`<section class="panel"><h2>${esc(b.short)} 게스트</h2><div class="inline mt"><input placeholder="이메일 주소" aria-label="초대 이메일">${btn('초대 미리보기','invite')}</div><p class="small dim mt">이 브랜드의 시안·성과를 볼 담당자를 초대하세요.</p></section>`:`<div class="grid cols-3 mb">${[['이번 달 발송 건수',b.sends,'이 브랜드의 여러 행사 합계'],['이번 달 발송비',b.cost,'다른 브랜드 비용 제외'],['브랜드 행사',b.events+'건','참여 데이터·권한 분리']].map(x=>`<div class="panel metric"><span class="metric-name">${x[0]}</span><div class="metric-value">${x[1]}</div><span class="metric-note">${x[2]}</span></div>`).join('')}</div><section class="panel"><div class="panel-head"><h2>${esc(b.short)} 발송 이력</h2><button class="btn secondary" data-create="brand-csv">월별 내역 CSV</button></div>${brandRows(b,true)}<div class="alert purple mt">현재 워크스페이스: ${esc(b.name)}<br>다른 브랜드의 참여자·발송 이력은 이 화면에 표시되지 않습니다.</div></section>`}`)}
function brandRows(b,sending){return `<div class="table-wrap"><table><thead><tr><th>행사</th><th>상태</th><th>${sending?'발송 건수':'운영 작업'}</th></tr></thead><tbody>${b.list.map(v=>`<tr><td>${esc(v[0])}</td><td>${pill(v[1],v[1]==='검토 중'?'review':v[1]==='시작 예정'?'scheduled':v[1]==='종료'?'ended':'')}</td><td>${sending?v[2]:b.id==='lumiere'?'<a class="text-link" href="#operate">행사 확인 ↗</a>':'<span class="dim">브랜드 행사 예시</span>'}</td></tr>`).join('')}</tbody></table></div>`}
const originalHome=home;home=function(){let h=originalHome();let i=0;return h.replace(/<a class="brand-row" href="#workspace">/g,()=>`<a class="brand-row" href="#workspace-detail" data-brand="${brands[i++].id}">`)};
const originalEditor=editor;editor=function(p){let h=originalEditor(p);if(!state.creationCustom)return h;const b=currentBrand(),t=currentTemplate();h=h.replaceAll('루미에르 성수 팝업 룰렛',`${esc(b.short)} ${esc(t.type)} 이벤트`).replace('두잇파이브 룰렛 템플릿 기반',`두잇파이브 ${t.type} 템플릿 기반`).replace('룰렛 템플릿에 브랜드 색상',`${t.type} 템플릿에 브랜드 색상`).replace('루미에르 코스메틱',esc(b.name));h=h.replace('<option>룰렛</option><option>스크래치</option>',`<option>${t.type}</option><option>룰렛</option><option>스크래치</option><option>퀴즈</option>`);h=h.replace('<div class="editor-grid">',`<div class="creation-context">선택한 템플릿 <b>${t.title}</b><a href="#templates" class="text-link">템플릿 다시 선택 ↗</a></div><div class="editor-grid">`);return h};
const originalPhone=phone;phone=function(mode='game',large=false){if(!state.creationCustom||mode!=='game')return originalPhone(mode,large);const t=currentTemplate();if(t.kind==='wheel')return originalPhone(mode,large).replaceAll('LUMIÈRE',esc(currentBrand().short)).replaceAll('루미에르',esc(currentBrand().short));return `<div class="phone"><div class="phone-notch"></div><div class="phone-body" style="--stage:${t.stage};--paper:${t.paper};--ink:${t.ink};--accent:${t.accent};background:${t.paper};min-height:520px"><div class="lumiere" style="color:${t.ink}">${esc(currentBrand().short)}</div><h2 style="color:${t.ink}">${t.headline}</h2><p>${t.desc}</p><div style="transform:scale(1.6);transform-origin:center;margin:50px auto 60px;width:122px">${gameSketch(t)}</div><button class="phone-button" style="background:${t.accent}" data-action="preview-other">${t.kind==='quiz'?'퀴즈 시작':t.kind==='scratch'?'당첨 확인하기':'게임 시작'}</button><p class="mt">디자인 미리보기 · 선택한 템플릿 적용</p></div></div>`};
const originalBind=bind;bind=function(){originalBind();app.querySelectorAll('[data-prompt]').forEach(n=>n.onclick=()=>{state.createPrompt=n.dataset.prompt;document.getElementById('create-prompt').value=state.createPrompt;document.getElementById('create-prompt').focus()});app.querySelectorAll('[data-tplfilter]').forEach(n=>n.onclick=()=>{state.templateFilter=n.dataset.tplfilter;const p=document.getElementById('create-prompt');if(p)state.createPrompt=p.value;render()});app.querySelectorAll('[data-preview]').forEach(n=>n.onclick=()=>previewTemplate(n.dataset.preview));app.querySelectorAll('[data-use]').forEach(n=>n.onclick=()=>{const p=document.getElementById('preview-brand');if(p)state.brandId=p.value;useTemplate(n.dataset.use)});app.querySelectorAll('[data-favorite]').forEach(n=>n.onclick=()=>{const id=n.dataset.favorite;state.favorites=state.favorites.includes(id)?state.favorites.filter(v=>v!==id):[...state.favorites,id];document.getElementById('template-grid').innerHTML=galleryCards();bind()});app.querySelectorAll('[data-brand]').forEach(n=>n.onclick=e=>{e.preventDefault();state.brandId=n.dataset.brand;go('workspace-detail')});app.querySelectorAll('[data-create]').forEach(n=>n.onclick=()=>createAction(n.dataset.create));const search=document.getElementById('template-search');if(search)search.oninput=()=>{state.templateSearch=search.value;document.getElementById('template-grid').innerHTML=galleryCards();bind()};const prompt=document.getElementById('create-prompt');if(prompt)prompt.oninput=()=>state.createPrompt=prompt.value;const brand=document.getElementById('create-brand');if(brand)brand.onchange=()=>state.brandId=brand.value;const sw=document.getElementById('brand-switch');if(sw)sw.onchange=()=>{state.brandId=sw.value;render()};};
function createAction(a){if(a==='close'){document.querySelector('.modal-overlay')?.remove();return}if(a==='brand-create'){go('templates');return}if(a==='brand-csv'){const b=currentBrand();download(`${b.id}-sending.csv`,'\ufeff브랜드,행사,상태,발송 건수\n'+b.list.map(v=>[b.name,...v].join(',')).join('\n'),'text/csv');return}if(a==='generate'){state.createPrompt=document.getElementById('create-prompt').value;if(!state.createPrompt.trim())return toast('만들고 싶은 행사를 알려주세요.');const p=state.createPrompt;state.selectedTemplate=/스크래치/.test(p)?'nova-scratch':/퀴즈/.test(p)?'green-quiz':/메모리|카드/.test(p)?'violet-memory':/슬롯/.test(p)?'gold-slot':/반응|속도/.test(p)?'orange-speed':'lumiere-wheel';state.creationCustom=true;state.generated=true;state.applied=false;state.editorTab='디자인';go('editor');toast('행사 설명에 맞는 게임 초안을 준비했습니다.');}}
const originalAction=action;action=function(a,n){if(a==='new'){go('templates');return}if(a==='brand-new'){app.insertAdjacentHTML('beforeend','<div class="modal-overlay"><div class="modal"><div class="between"><h2>브랜드 추가</h2><button data-create="close" aria-label="닫기">✕</button></div><div class="field"><label>브랜드 이름</label><input id="brand-new-name" placeholder="새 브랜드 이름"></div><button class="btn wide" data-action="brand-confirm">워크스페이스 등록</button></div></div>');bind();return}if(a==='brand-confirm'){const name=document.getElementById('brand-new-name').value.trim();if(!name)return toast('브랜드 이름을 입력해주세요.');retainEvent();state.eventName='';const id='brand-'+brands.length;brands.push({id,name,short:name,initial:name[0],color:'#8978bd',soft:'#eeebf8',events:0,active:0,sends:'0',cost:'0원',description:'새로 추가한 브랜드',list:[]});state.brandId=id;go('workspace-detail');toast('브랜드를 추가했습니다.');return}if(a==='preview-other'){toast(`${currentTemplate().type} 디자인 미리보기 · 실제 경품 발송 없음`);return}originalAction(a,n)};
screens.find(s=>s[0]==='workspace')[2]='전체 브랜드 워크스페이스';screens.splice(8,0,['workspace-detail','C-03 상세','브랜드별 기능 탭']);screens.splice(screens.length-1,0,['templates','C-04','AI 행사 만들기·템플릿']);
const originalRender=render;render=function(){if(route()==='workspace-detail'){document.body.dataset.screen='workspace-detail';app.innerHTML=brandDetail();document.title=currentBrand().name+' · 두잇킷';bind()}else originalRender()};
render();

const originalNav=navItem;navItem=function(r,t,k){let h=originalNav(r,t,k);return r==='workspace'&&route()==='workspace-detail'?h.replace('class=""','class="active"'):h};render();
